"""Screen 0 — Welcome & architecture overview."""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw

from .base import BasePage
from ..svg_assets import make_shield_image
from ..state import WizardState
from typing import Callable


class WelcomeScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="Welcome", tag="welcome")

    def _build(self):
        # Hero section
        hero = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=8)
        hero.set_margin_bottom(8)

        icon = make_shield_image(color="#546ac1", pixel_size=64)
        icon.set_margin_bottom(12)
        hero.append(icon)

        title = Gtk.Label(label="Welcome to BulwarkOS")
        title.add_css_class("title-1")
        title.set_justify(Gtk.Justification.CENTER)
        hero.append(title)

        sub = Gtk.Label(
            label="This wizard configures your hardware isolation stack.\n"
                  "First run takes 5–10 minutes and requires a reboot.\n"
                  "Re-running skips steps that are already complete."
        )
        sub.add_css_class("body")
        sub.get_style_context().add_class("dim-label")
        sub.set_justify(Gtk.Justification.CENTER)
        sub.set_wrap(True)
        hero.append(sub)

        self._body.append(hero)

        # What the wizard does
        steps_group = Adw.PreferencesGroup()
        steps_group.set_title("What this wizard does")

        steps = [
            ("dialog-information-symbolic",
             "Detects your hardware",
             "Confirms IOMMU is active and enumerates IOMMU groups."),
            ("network-wired-symbolic",
             "Configures NIC passthrough",
             "Passes your physical NICs to sys-net via VFIO. The host never touches the network directly after setup."),
            ("computer-symbolic",
             "Provisions AppVMs",
             "Creates sys-net, sys-firewall, and your chosen AppVMs (personal, work, banking, etc.)."),
            ("security-high-symbolic",
             "Writes kernel & VFIO config",
             "Appends IOMMU kernel args, writes modprobe.d config, and rebuilds the initramfs. Skipped if already done."),
            ("system-restart-symbolic",
             "Requires one reboot",
             "VFIO passthrough becomes active after the next boot. AppVMs can be started immediately after."),
        ]

        for icon_name, row_title, row_sub in steps:
            row = Adw.ActionRow()
            row.set_title(row_title)
            row.set_subtitle(row_sub)
            img = Gtk.Image.new_from_icon_name(icon_name)
            img.set_pixel_size(16)
            row.add_prefix(img)
            steps_group.add(row)

        self._body.append(steps_group)

        # Architecture summary
        arch_group = Adw.PreferencesGroup()
        arch_group.set_title("How BulwarkOS isolates your system")

        arch_items = [
            ("network-wired-symbolic",
             "sys-net",
             "Physical NICs received via VFIO. The host has no direct network access after setup."),
            ("firewall-symbolic",
             "sys-firewall",
             "All AppVM traffic routes through this VM. nftables enforces traffic policy."),
            ("computer-symbolic",
             "AppVMs",
             "Each trust domain (personal, work, banking, disposable) runs in its own isolated KVM VM."),
            ("user-trash-symbolic",
             "Disposable VM",
             "Boots Tails OS from ISO. Amnesic — all session data is wiped on shutdown. Traffic routed through Tor."),
        ]

        for icon_name, row_title, row_sub in arch_items:
            row = Adw.ActionRow()
            row.set_title(row_title)
            row.set_subtitle(row_sub)
            img = Gtk.Image.new_from_icon_name(icon_name)
            img.set_pixel_size(16)
            row.add_prefix(img)
            arch_group.add(row)

        self._body.append(arch_group)

        # Reboot notice
        note = Adw.Banner()
        note.set_title(
            "A reboot is required after setup to activate VFIO passthrough. "
            "Steps already completed from a previous run will be skipped automatically."
        )
        note.set_revealed(True)
        self._body.append(note)

        btn_row = self.make_button_row(
            back_label=None,
            back_cb=None,
            next_label="Get Started",
            next_cb=lambda: self.go_to("detect"),
        )
        self._body.append(btn_row)
